		private global::System.Collections.Generic.Dictionary<uint, uint> createZukanDataClone() {
            Dictionary<uint, uint> zukanData = new Dictionary<uint, uint>();
            for (int i = 0; i < m_setupParam.party.Length; i++)
            {
                PokeParty party = m_setupParam.party[i];
                if (party == null)
                    continue;
                for (uint idx = 0; idx < party.GetMemberCount(); idx++)
                {
                    PokemonParam pp = party.GetMemberPointer(idx);
                    if (pp == null || pp.IsNull())
                        continue;
                    uint monsno = (uint)pp.GetMonsNo();
                    uint status = (uint)ZukanWork.GetStatus(monsno);
                    if (!zukanData.ContainsKey(monsno))
                        zukanData.Add(monsno, status);
                }
            }
            return zukanData;
        }
