		private void storeBattleResult() {
            if (m_setupParam.recordDataMode == BtlRecordDataMode.BTL_RECORDDATA_PLAY)
            {
                m_setupParam.recPlayCompleteFlag = checkRecReadComplete();
                BattleResult.ApplyBattlePartyData(m_setupParam, m_battleEnvForServer, m_battleEnvForClient, this, 0);
                return;
