            BtlResult result = checkWinner(m_myClientID);
            Bspstore_RecordData();
            Bspstore_KenteiData();
            BattleResult.ApplyBattlePartyData(m_setupParam, m_battleEnvForServer, m_battleEnvForClient, this, m_myClientID);
            if (m_server != null || m_cmdCheckServer != null)
                BattleResult.ApplyRecordHeader(m_setupParam, this, m_myClientID, result);
            if (m_rule == BtlRule.BTL_RULE_SAFARI)
                m_setupParam.safariBallNum = (int)m_battleEnvForServer.GetBattleCounter().Get(BattleCounter.UniqueCounter.SAFARI_BALL_COUNT);
            uint bonusMoney = GetBonusMoney();
            if (result == BtlResult.BTL_RESULT_LOSE || result == BtlResult.BTL_RESULT_DRAW)
                m_setupParam.getMoney = -(int)m_loseMoney;
            else if (result == BtlResult.BTL_RESULT_WIN)
                m_setupParam.getMoney = (int)(m_regularMoney + bonusMoney);
        }
		private bool isBgmFadeOutDisable() {
            BtlResult result = m_setupParam.result;
            if (!GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_FLAG_WIN_BGM_CONTINUE))
                return false;
            if (m_setupParam.recordDataMode == BtlRecordDataMode.BTL_RECORDDATA_PLAY)
                return false;
            switch (result)
            {
                case BtlResult.BTL_RESULT_WIN:
                case BtlResult.BTL_RESULT_RUN:
                case BtlResult.BTL_RESULT_RUN_ENEMY:
                    break;
                default:
                    return false;
            }
            switch (m_setupParam.competitor)
            {
                case BtlCompetitor.BTL_COMPETITOR_WILD:
                case BtlCompetitor.BTL_COMPETITOR_TRAINER:
                case BtlCompetitor.BTL_COMPETITOR_DEMO_CAPTURE:
                    break;
                default:
                    return false;
            }
            return !GetClient(0).isEvolveEnablePokeExsist();
        }
		private bool checkRecReadComplete() {
            for (byte clientID = 0; clientID < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientID++)
            {
                if (!BattleRule.IsClientExist(m_rule, m_setupParam.multiMode, (BTL_CLIENT_ID)clientID))
                    continue;
                if (!m_recReader.IsReadComplete(clientID))
                    return false;
            }
            return true;
        }
