            setSubProc(setup_alone_single);
        }
		private void setSubProcForCleanUp(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM setup_param) {
            setSubProc(cleanup_common);
        }
		private void setupCommon_TrainerParam(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM sp) {
            if (m_setupParam.recordDataMode == BtlRecordDataMode.BTL_RECORDDATA_PLAY)
            {
                for (byte clientID = 0; clientID < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientID++)
                {
                    if (BattleRule.IsClientExist(m_rule, m_setupParam.multiMode, (BTL_CLIENT_ID)clientID))
                        trainerParam_SetupForRecPlay(clientID);
                }
                return;
            }
            if (sp.tr_data[0] == null)
                trainerParam_StorePlayer(m_trainerParam[0], m_playerStatus);
            else
                trainerParam_StoreNPCTrainer(m_trainerParam[0], sp.tr_data[0]);
            if (sp.tr_data[1] != null)
                trainerParam_StoreNPCTrainer(m_trainerParam[1], sp.tr_data[1]);
            if (sp.tr_data[3] != null)
                trainerParam_StoreNPCTrainer(m_trainerParam[3], sp.tr_data[3]);
            if (sp.tr_data[2] != null)
                trainerParam_StoreNPCTrainer(m_trainerParam[2], sp.tr_data[2]);
        }
		private void setupCommon_SetRecplayerClientMode(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM sp) {
            if (m_setupParam.recordDataMode != BtlRecordDataMode.BTL_RECORDDATA_PLAY)
                return;
            unsafe
            {
                m_recReader.Init(sp.recBuffer, sp.recDataSize);
            }
            m_client[0].SetRecordPlayerMode(m_recReader);
            m_client[1].SetRecordPlayerMode(m_recReader);
            if (m_client[2] != null)
                m_client[2].SetRecordPlayerMode(m_recReader);
            if (m_client[3] != null)
                m_client[3].SetRecordPlayerMode(m_recReader);
        }
		private void setupCommon_CreateViewModule(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM sp, global::Dpr.Battle.Logic.BtlBagMode bagMode) {
            BTL_CLIENT client;
            if (m_setupParam.recordDataMode == BtlRecordDataMode.BTL_RECORDDATA_PLAY)
                client = m_client[sp.commPos];
            else
                client = m_client[m_myClientID];
            BTLV_INIT_PARAM initParam = new BTLV_INIT_PARAM();
            initParam.mMainModule = this;
            initParam.mClient = client;
            initParam.mBattleEnv = m_battleEnvForClient;
            initParam.mBagMode = bagMode;
            initParam.mMsgSpeed = m_msgSpeed;
            m_viewCore = BattleViewFactory.CreateViewSystem(initParam);
            client.AttachViewCore(m_viewCore);
        }
		private bool setupCommon_InitViewModule() {
            if (!m_viewCore.Initialize())
                return false;
            if (m_setupParam.recordDataMode == BtlRecordDataMode.BTL_RECORDDATA_PLAY)
                m_viewCore.CMD_RecPlayer_Init((ushort)m_recReader.GetTurnCount());
            return true;
        }
		private void setupCommon_ClientPublicInformation(in global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM setupParam) {
            for (byte clientId = 0; clientId < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientId++)
            {
                MiseaiData miseaiData = setupParam.miseaiData[clientId];
                if (miseaiData.iPtrPartyFullMember != null)
                    setupCommon_ClientPublicInformation(m_clientPublicInformation[clientId], clientId, in miseaiData);
            }
        }
		private void setupCommon_ClientPublicInformation(global::Dpr.Battle.Logic.ClientPublicInformation publicInfo, byte clientId, in global::Dpr.Battle.Logic.MiseaiData miseaiData) {
            for (int i = 0; i < DefineConstants.BTL_PARTY_MEMBER_MAX; i++)
            {
                byte pokeID;
                if (miseaiData.memberSelectedIndex[i] < 0)
                    pokeID = PokeID.INVALID;
                else
                    pokeID = (byte)(GetClientBasePokeID(clientId) + miseaiData.memberSelectedIndex[i]);
                PokemonParam pp = miseaiData.iPtrPartyFullMember.GetMemberPointerConst((uint)i);
                MonsNo monsno = pp.IsEgg(EggCheckType.BOTH_EGG) ? MonsNo.TAMAGO : pp.GetMonsNo();
                ushort formno = pp.GetFormNo();
                Sex sex = pp.GetSex();
                byte level = (byte)pp.GetLevel();
                bool haveItem = pp.GetItem() != 0;
                publicInfo.PublishPokemon((byte)i, pokeID, monsno, formno, sex, level, haveItem);
            }
        }
		private bool setup_alone_single(ref int seq) {
            BATTLE_SETUP_PARAM sp = m_setupParam;
            switch (seq)
            {
                case 0:
                    setup_alone_common_ClientID(sp);
                    setupCommon_srcParty(sp);
                    _ = m_srcParty[1];
                    _ = m_srcPartyForServer[1];
                    setupCommon_TrainerParam(sp);
                    setSrcPartyToBattleEnv(m_battleEnvForClient, 0, false);
                    setSrcPartyToBattleEnv(m_battleEnvForClient, 1, false);
                    setSrcPartyToBattleEnv(m_battleEnvForServer, 0, true);
                    setSrcPartyToBattleEnv(m_battleEnvForServer, 1, true);
                    setupCommon_SetupBattleEnv();
                    setupCommon_CreateServerClient(in m_setupParam);
                    setupCommon_ClientPublicInformation(in m_setupParam);
                    setupCommon_SetRecplayerClientMode(sp);
                    setupCommon_CreateViewModule(sp, checkBagMode(sp));
                    seq++;
                    goto case 1;
                case 1:
                    if (!setupCommon_InitViewModule())
                        return false;
                    m_server.Startup();
                    setMainLoop(MainLoop_StandAlone);
                    return true;
            }
            return true;
        }
