                    setSrcPartyToBattleEnv(m_battleEnvForServer, 0, true);
                    setSrcPartyToBattleEnv(m_battleEnvForServer, 1, true);
                    setupCommon_SetupBattleEnv();
                    setupCommon_CreateServerClient(in m_setupParam);
                    setupCommon_ClientPublicInformation(in m_setupParam);
                    setupCommon_SetRecplayerClientMode(sp);
                    setupCommon_CreateViewModule(sp, checkBagMode(sp));
                    seq++;
                    goto case 1;
                case 1:
                    if (!setupCommon_InitViewModule())
                        return false;
                    m_server.Startup();
                    setMainLoop(MainLoop_StandAlone);
                    return true;
            }
            return true;
        }
		private bool setup_alone_double_multi(ref int seq) {
            pSubProc proc;
            switch (seq)
            {
                case 1: proc = setup_alone_double_multi_00; break;
                case 2: proc = setup_alone_double_multi_01; break;
                case 3: proc = setup_alone_double_multi_02; break;
                case 4: proc = setup_alone_double_multi_04; break;
                case 5: proc = setup_alone_double_multi_06; break;
                case 6: proc = setup_alone_double_multi_07; break;
                case 7: proc = setup_alone_double_multi_08; break;
                case 8: proc = setup_alone_double_multi_09; break;
                default: proc = null; break;
            }
            if (seq == 0)
            {
                m_setupStep = 0;
            }
            else
            {
                if (seq > 8)
                    return true;
                if (!proc(ref m_setupStep))
                    return false;
                m_setupStep = 0;
            }
            seq++;
            return false;
        }
		private bool setup_alone_double_multi_00(ref int seq) {
            m_myClientID = 0;
            return true;
        }
		private bool setup_alone_double_multi_01(ref int seq) {
            BATTLE_SETUP_PARAM sp = m_setupParam;
            setup_alone_common_ClientID(sp);
            setupCommon_srcParty(sp);
            return true;
        }
		private bool setup_alone_double_multi_02(ref int seq) {
            BATTLE_SETUP_PARAM sp = m_setupParam;
            if (sp.recordDataMode == BtlRecordDataMode.BTL_RECORDDATA_PLAY)
            {
                if (seq > 4)
                    return true;
                if (BattleRule.IsClientExist(m_rule, sp.multiMode, (BTL_CLIENT_ID)(byte)seq))
                    trainerParam_SetupForRecPlay((byte)seq);
                seq++;
                return false;
            }
            trainerParam_StorePlayer(m_trainerParam[0], m_playerStatus);
            trainerParam_StoreNPCTrainer(m_trainerParam[1], sp.tr_data[1]);
            if (BattleRule.IsClientExist(m_rule, m_setupParam.multiMode, BTL_CLIENT_ID.BTL_CLIENT_PARTNER))
                trainerParam_StoreNPCTrainer(m_trainerParam[2], sp.tr_data[2]);
            if (BattleRule.IsClientExist(m_rule, m_setupParam.multiMode, BTL_CLIENT_ID.BTL_CLIENT_ENEMY2))
                trainerParam_StoreNPCTrainer(m_trainerParam[3], sp.tr_data[3]);
            return true;
        }
		private bool setup_alone_double_multi_03(ref int seq) {
            return true;
        }
		private bool setup_alone_double_multi_04(ref int seq) {
            while (seq <= 9)
            {
                int clientID = seq / 2;
                if (BattleRule.IsClientExist(m_rule, m_setupParam.multiMode, (BTL_CLIENT_ID)(byte)clientID))
                {
                    bool forServer = (seq & 1) != 0;
                    setSrcPartyToBattleEnv(forServer ? m_battleEnvForServer : m_battleEnvForClient, (byte)clientID, forServer);
                    seq++;
                    break;
                }
                seq++;
            }
            return seq > 9;
        }
		private bool setup_alone_double_multi_05(ref int seq) {
            return true;
        }
		private bool setup_alone_double_multi_06(ref int seq) {
            setupCommon_SetupBattleEnv();
            setupCommon_CreateServerClient(in m_setupParam);
            setupCommon_ClientPublicInformation(in m_setupParam);
            return true;
        }
		private bool setup_alone_double_multi_07(ref int seq) {
            BATTLE_SETUP_PARAM sp = m_setupParam;
            if (sp.recordDataMode == BtlRecordDataMode.BTL_RECORDDATA_PLAY)
            {
                unsafe
                {
                    m_recReader.Init(sp.recBuffer, sp.recDataSize);
                }
                for (byte clientID = 0; clientID < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientID++)
                {
                    if (BattleRule.IsClientExist(m_rule, m_setupParam.multiMode, (BTL_CLIENT_ID)clientID))
                        m_client[clientID].SetRecordPlayerMode(m_recReader);
                }
            }
            setupCommon_CreateViewModule(sp, checkBagMode(sp));
            setupCommon_InitViewModule();
            return true;
        }
		private bool setup_alone_double_multi_08(ref int seq) {
            return setupCommon_InitViewModule();
        }
		private bool setup_alone_double_multi_09(ref int seq) {
            m_server.Startup();
            setMainLoop(MainLoop_StandAlone);
            return true;
        }
		private bool setup_alone_raid(ref int seq) {
            switch (seq)
            {
                case 0:
                    setup_alone_common_ClientID(m_setupParam);
                    setup_raid_srcParty();
                    setup_raid_trainerParam();
                    setup_raid_battleEnv(m_battleEnvForClient, false);
                    setup_raid_battleEnv(m_battleEnvForServer, true);
                    setup_raid_boss(m_battleEnvForClient);
                    setup_raid_boss(m_battleEnvForServer);
                    setupCommon_SetupBattleEnv();
                    setupCommon_CreateServerClient(in m_setupParam);
                    setupCommon_ClientPublicInformation(in m_setupParam);
                    setupCommon_SetRecplayerClientMode(m_setupParam);
                    setupCommon_CreateViewModule(m_setupParam, checkBagMode(m_setupParam));
                    seq++;
                    goto case 1;
                case 1:
                    if (!setupCommon_InitViewModule())
                        return false;
                    m_server.Startup();
                    setMainLoop(MainLoop_StandAlone);
                    return true;
            }
            return true;
        }
		private bool setup_comm_raid(ref int seq) {
            pSubProc proc;
            switch (seq)
            {
                case 1: proc = setupseq_comm_determine_server; break;
                case 2: proc = setupseq_comm_store_party_data; break;
                case 3: proc = setupseq_comm_store_player_data; break;
                case 4: proc = setupseq_comm_create_server_client; break;
                case 5: proc = setupseq_comm_raid; break;
                case 6: proc = setupseq_comm_start_server; break;
                default: proc = null; break;
            }
            if (seq == 0)
            {
                m_MultiAIClientNum = 1;
                m_MultiAIClientID[0] = (byte)BTL_CLIENT_ID.BTL_CLIENT_RAID_BOSS;
                switch (m_setupParam.multiMode)
                {
                    case BtlMultiMode.BTL_MULTIMODE_RAID_PPPA_A:
                        m_MultiAIClientNum = 2;
                        m_MultiAIClientID[0] = (byte)BTL_CLIENT_ID.BTL_CLIENT_RAID_BOSS;
                        m_MultiAIClientID[1] = (byte)BTL_CLIENT_ID.BTL_CLIENT_RAID_PLAYER_3;
                        break;
                    case BtlMultiMode.BTL_MULTIMODE_RAID_PPAA_A:
                        m_MultiAIClientNum = 3;
                        m_MultiAIClientID[0] = (byte)BTL_CLIENT_ID.BTL_CLIENT_RAID_BOSS;
                        m_MultiAIClientID[1] = (byte)BTL_CLIENT_ID.BTL_CLIENT_RAID_PLAYER_2;
                        m_MultiAIClientID[2] = (byte)BTL_CLIENT_ID.BTL_CLIENT_RAID_PLAYER_3;
                        break;
                    case BtlMultiMode.BTL_MULTIMODE_RAID_PPPP_A:
                        m_MultiAIClientNum = 1;
                        m_MultiAIClientID[0] = (byte)BTL_CLIENT_ID.BTL_CLIENT_RAID_BOSS;
                        break;
                }
                setup_alone_common_ClientID(m_setupParam);
                m_setupStep = 0;
            }
            else
            {
                if (seq > 6)
                    return true;
                if (!proc(ref m_setupStep))
                    return false;
                m_setupStep = 0;
            }
            seq++;
            return false;
        }
		private bool setupseq_comm_raid(ref int seq) {
            setup_raid_boss(m_battleEnvForClient);
            setup_raid_boss(m_battleEnvForServer);
            return true;
        }
