		private void setupCommon_SetupBattleEnv_BattleTalk(global::Dpr.Battle.Logic.BattleEnv env) { }
		public void setupCommon_CreateServerClient(in global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM setupParam) {
            ServerClientFactory.Input input = new ServerClientFactory.Input();
            ServerClientFactory.Output output = new ServerClientFactory.Output();
            input.adapterFactory = m_adapterFactory;
            input.rule = setupParam.rule;
            input.multiMode = setupParam.multiMode;
            input.commMode = setupParam.commMode;
            input.bagMode = BtlBagMode.BBAG_MODE_NORMAL;
            input.isRecordPlayMode = IsRecordPlayMode();
            input.myClientId = (BTL_CLIENT_ID)m_myClientID;
            input.amIServer = CheckImServerMachine();
            input.mainModule = this;
            input.randomSeed = m_randomSeed;
            input.battleEnvForClient = m_battleEnvForClient;
            input.battleEnvForServer = m_battleEnvForServer;
            input.sendDataContainerForServerSend = SendDataContainerFactory.GetServerSendContainer();
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                input.sendDataContainerForClientSend[i] = SendDataContainerFactory.GetClientSendContainer((BTL_CLIENT_ID)i);
                input.sendDataContainerForClientReceive[i] = SendDataContainerFactory.GetClientReceiveContainer((BTL_CLIENT_ID)i);
            }
            ServerClientFactory.CreateServerClient(in input, output);
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                m_client[i] = output.localClients[i];
                m_dummyClient[i] = output.dummyClients[i];
            }
            if (IsRecordPlayMode() || CheckImServerMachine())
                m_server = output.server;
            else
                m_cmdCheckServer = output.server;
        }
		private global::Dpr.Battle.Logic.BtlBagMode checkBagMode(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM sp) {
            return BtlBagMode.BBAG_MODE_NORMAL;
        }
		private void setup_alone_common_ClientID(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM sp) {
            m_myClientID = sp.commPos;
            m_myOrgPos = GetClientPokePos(m_myClientID, 0);
        }
		private void setupCommon_srcParty(global::Dpr.Battle.Logic.BATTLE_SETUP_PARAM sp) {
            byte relation0 = ClientIDtoRelation(m_myClientID, 0);
            byte relation1 = ClientIDtoRelation(m_myClientID, 1);
            srcParty_Set(0, in sp.party[relation0]);
            srcParty_Set(1, in sp.party[relation1]);
            byte relation2 = ClientIDtoRelation(m_myClientID, 2);
            byte relation3 = ClientIDtoRelation(m_myClientID, 3);
            if (sp.party[relation2] != null)
                srcParty_Set(2, in sp.party[relation2]);
            if (sp.party[relation3] != null)
                srcParty_Set(3, in sp.party[relation3]);
        }
		private void setSrcPartyToBattleEnv(global::Dpr.Battle.Logic.BattleEnv battleEnv, byte clientID, bool forServer) {
            PokeParty[] srcParty = forServer ? m_srcPartyForServer : m_srcParty;
            PartyDesc partyDesc = m_setupParam.partyDesc[clientID];
            battleEnv.GetPokeCon().SetParty(clientID, srcParty[clientID], in partyDesc, m_trainerParam[clientID].playerStatus);
        }
		public byte ClientIDtoRelation(byte myClientID, byte targetClientID) {
            if (myClientID == targetClientID)
                return 0;
            if (PokemonPosition.GetClientSide(m_rule, (BTL_CLIENT_ID)myClientID) == PokemonPosition.GetClientSide(m_rule, (BTL_CLIENT_ID)targetClientID))
                return 2;
            return (byte)(targetClientID < 2 ? 1 : 3);
        }
		private bool cleanup_common(ref int seq) {
            if (m_viewCore != null)
            {
                if (!m_viewCore.FinalizeApp())
                    return false;
                m_viewCore = null;
            }
            for (int i = 0; i < m_client.Length; i++)
            {
                if (m_client[i] != null)
                    m_client[i].Dispose();
                m_client[i] = null;
            }
            for (int i = 0; i < m_dummyClient.Length; i++)
            {
                if (m_dummyClient[i] != null)
                    m_dummyClient[i].Dispose();
                m_dummyClient[i] = null;
            }
            if (m_server != null)
                m_server = null;
            if (m_cmdCheckServer != null)
                m_cmdCheckServer = null;
            m_zukanDataOnBattleStart = null;
            BattleUnmanagedMem.FreeAll();
            return true;
        }
		private bool setup_comm_single(ref int seq) {
            pSubProc proc;
            switch (seq)
            {
                case 1: proc = setupseq_comm_determine_server; break;
                case 2: proc = setupseq_comm_store_party_data; break;
                case 3: proc = setupseq_comm_store_player_data; break;
                case 4: proc = setupseq_comm_create_server_client; break;
                case 5: proc = setupseq_comm_start_server; break;
                default: proc = null; break;
            }
            if (seq == 0)
            {
                setup_alone_common_ClientID(m_setupParam);
                m_setupStep = 0;
            }
            else
            {
                if (seq > 5)
                    return true;
                if (!proc(ref m_setupStep))
                    return false;
                m_setupStep = 0;
            }
            seq++;
            return false;
        }
		private bool setup_comm_double(ref int seq) {
            pSubProc proc;
            switch (seq)
            {
                case 1: proc = setupseq_comm_determine_server; break;
                case 2: proc = setupseq_comm_store_party_data; break;
                case 3: proc = setupseq_comm_store_player_data; break;
                case 4: proc = setupseq_comm_create_server_client; break;
                case 5: proc = setupseq_comm_start_server; break;
                default: proc = null; break;
            }
            if (seq == 0)
            {
                if (m_setupParam.multiMode == BtlMultiMode.BTL_MULTIMODE_PP_AA)
                {
                    m_MultiAIClientNum = 2;
                    m_MultiAIClientID[0] = (byte)BTL_CLIENT_ID.BTL_CLIENT_ENEMY1;
                    m_MultiAIClientID[1] = (byte)BTL_CLIENT_ID.BTL_CLIENT_ENEMY2;
                }
                setup_alone_common_ClientID(m_setupParam);
                m_setupStep = 0;
            }
            else
            {
                if (seq > 5)
                    return true;
                if (!proc(ref m_setupStep))
                    return false;
                m_setupStep = 0;
            }
            seq++;
            return false;
        }
		private bool setupseq_comm_determine_server(ref int seq) {
            if (m_iPtrNetClient.HasErrorOccured())
            {
                m_fCommError = true;
                return true;
            }
            switch (seq)
            {
                case 0:
                    m_iPtrNetClient.StartDetermineServer();
                    seq = 1;
                    return false;
                case 1:
                    if (!m_iPtrNetClient.IsDeterminedServer())
                        return false;
                    m_setupParam.commServerVer = m_iPtrNetClient.GetServerVersion();
                    if (m_iPtrNetClient.CheckImServer())
                        seq = 2;
                    else
                        seq = 3;
                    return false;
                case 2:
                    {
                        Net.Data.ServerParam serverParam = new Net.Data.ServerParam();
                        serverParam.randomSeed = m_randomSeed;
                        serverParam.LimitTimeGame = m_setupParam.LimitTimeGame;
                        serverParam.LimitTimeClient = m_setupParam.LimitTimeClient;
                        serverParam.LimitTimeCommand = m_setupParam.LimitTimeCommand;
                        serverParam.msgSpeed = (byte)MSGSPEED.MSGSPEED_FAST;
                        serverParam.fWazaEffectEnable = true;
                        m_iPtrNetClient.StartNotifyServerParam(in serverParam);
                        seq = 4;
                        return false;
                    }
                case 3:
                    if (m_iPtrNetClient.StartWaitForNotifyServerParam())
                        seq = 4;
                    return false;
                case 4:
                    {
                        if (!m_iPtrNetClient.IsNotifiedServerParam())
                            return false;
                        Net.Data.ServerParam serverParam = m_iPtrNetClient.GetServerParam();
                        m_setupParam.recRandSeed = serverParam.randomSeed;
                        m_randomSeed = serverParam.randomSeed;
                        m_fWazaEffectEnable = serverParam.fWazaEffectEnable;
                        m_msgSpeed = (MSGSPEED)serverParam.msgSpeed;
                        m_LimitTimeGame = serverParam.LimitTimeGame;
                        m_LimitTimeClient = serverParam.LimitTimeClient;
                        m_LimitTimeCommand = serverParam.LimitTimeCommand;
                        return true;
                    }
                case 5:
                    return true;
            }
            return false;
        }
		private bool setupseq_comm_store_party_data(ref int seq) {
            for (byte clientID = 0; clientID < (byte)BTL_CLIENT_ID.BTL_CLIENT_NUM; clientID++)
            {
                if (!BattleRule.IsClientExist(m_rule, m_setupParam.multiMode, (BTL_CLIENT_ID)clientID))
                    continue;
                PokeParty party = m_setupParam.party[clientID];
                srcParty_Set(clientID, in party);
                setSrcPartyToBattleEnv(m_battleEnvForClient, clientID, false);
                setSrcPartyToBattleEnv(m_battleEnvForServer, clientID, true);
            }
            return true;
        }
		private bool setupseq_comm_store_player_data(ref int seq) {
            BtlRule rule = m_rule;
            byte clientNum = BattleRule.GetClientNum(rule, m_setupParam.multiMode);
            for (int i = 0; i < clientNum; i++)
            {
                if (BattleRule.IsClientAi(rule, m_setupParam.commMode, m_setupParam.multiMode, (BTL_CLIENT_ID)i))
                    continue;
                MyStatus playerData = m_setupParam.playerStatus[i];
                trainerParam_StorePlayer(m_trainerParam[i], playerData);
            }
            for (int i = 0; i < m_MultiAIClientNum; i++)
            {
                byte clientID = m_MultiAIClientID[i];
                BSP_TRAINER_DATA trData = m_setupParam.tr_data[clientID];
                trainerParam_StoreNPCTrainer(m_trainerParam[clientID], trData);
            }
            return true;
        }
		private bool setupseq_comm_create_server_client(ref int seq) {
            if (m_iPtrNetClient.HasErrorOccured())
            {
                m_fCommError = true;
                return true;
            }
            setupCommon_SetupBattleEnv();
            setupCommon_CreateServerClient(in m_setupParam);
            setupCommon_ClientPublicInformation(in m_setupParam);
            setupCommon_SetRecplayerClientMode(m_setupParam);
            return true;
        }
		private bool setupseq_comm_start_server(ref int seq) {
            if (m_iPtrNetClient.HasErrorOccured() && seq != 1)
            {
                m_fCommError = true;
                return true;
            }
            switch (seq)
            {
                case 0:
                    setupCommon_CreateViewModule(m_setupParam, checkBagMode(m_setupParam));
                    seq++;
                    goto case 1;
                case 1:
                    if (!setupCommon_InitViewModule())
                        return false;
                    seq++;
                    return false;
                case 2:
                    if (CheckImServerMachine())
                    {
                        setMainLoop(MainLoop_Comm_Server);
                        m_server.Startup();
                    }
                    else
                    {
                        setMainLoop(MainLoop_Comm_NotServer);
                    }
                    seq++;
                    return false;
                case 3:
                    if (m_rule == BtlRule.BTL_RULE_RAID)
                    {
                        if (m_setupParam.commMode == BtlCommMode.BTL_COMM_WIFI)
                        {
                            if (m_iPtrNetClient == null)
                            {
                                m_fCommError = true;
                                return true;
                            }
                        }
                        else if (m_setupParam.commMode == BtlCommMode.BTL_COMM_WIRELESS)
                        {
                            m_fCommError = true;
                            return true;
                        }
                    }
                    seq = 4;
                    return false;
            }
            return true;
        }
		private bool MainLoop_StandAlone() {
            m_server.MainLoop();
            bool quit = false;
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                if (m_client[i] != null)
                    quit |= m_client[i].Main();
            }
            return quit;
        }
		private bool MainLoop_Comm_Server() {
            if (m_fCommError)
            {
                if (m_fCommErrorMainQuit)
                    return true;
            }
            else if (m_iPtrNetClient.HasErrorOccured())
            {
                OnCommError();
            }
            watchRemoteClientCommunication();
            bool serverQuit = m_server.MainLoop();
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                if (m_client[i] != null && !m_fClientQuit[i])
                    m_fClientQuit[i] = m_client[i].Main();
            }
            bool allClientQuit = CheckAllClientQuit();
            return serverQuit | allClientQuit;
        }
		private void watchRemoteClientCommunication() {
            if (!canLaunchDammyClient())
                return;
            BtlRule rule = m_rule;
            BtlMultiMode multiMode = m_setupParam.multiMode;
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                // The shipped build only evaluates the existence test; nothing uses its result (02034164-02034248).
                if (m_client[i] == null)
                    BattleRule.IsClientExist(rule, multiMode, (BTL_CLIENT_ID)i);
            }
        }
		private void watchMyClientCommunication() { }
		private bool canLaunchDammyClient() {
            if (m_server == null || !BattleRule.IsDummyClientSwitchEnable(m_rule))
                return false;
            return m_server.IsWaitingClientReply();
        }
		private void launchDammyClient(global::Dpr.Battle.Logic.BTL_CLIENT_ID clientId) {
            if (m_client[(int)clientId] != null)
                return;
            m_client[(int)clientId] = m_dummyClient[(int)clientId];
            m_client[(int)clientId].GetAdapter().ChangeToNonCommMode();
            m_dummyClient[(int)clientId] = null;
            if (m_fCommError)
                m_client[(int)clientId].NotifyCommError();
        }
		private bool MainLoop_Comm_NotServer() {
            if (m_fCommError)
            {
                if (m_fCommErrorMainQuit)
                    return true;
            }
            else if (m_iPtrNetClient.HasErrorOccured())
            {
                OnCommError();
            }
            bool quit = false;
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                if (m_client[i] != null)
                    quit |= m_client[i].Main();
            }
            watchRemoteServerLoss();
            return quit;
        }
		private void watchRemoteServerLoss() {
            if (m_server != null || !CheckImServerMachine())
                return;
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                if (m_client[i] != null && !m_client[i].IsWaitingAdapterCommand())
                    return;
            }
            changeServerSelf();
        }
		private void changeServerSelf() {
            m_server = m_cmdCheckServer;
            m_cmdCheckServer = null;
            SendDataContainer receiveContainer = SendDataContainerFactory.GetClientReceiveContainer((BTL_CLIENT_ID)m_myClientID);
            SendDataContainerFactory.GetServerSendContainer().CopyFrom(in receiveContainer);
            m_server.StartupAsNewServer();
            m_client[m_myClientID].DetachCmdCheckServer();
            setMainLoop(MainLoop_Comm_Server);
        }
		private bool MainLoop_Comm_Error() {
            return true;
        }
		public void OnCommError() {
            m_fCommError = true;
            NotifyCommErrorToLocalClient();
            if (m_isFinalizeStarted)
                return;
            m_viewCore.SetUIControlEnableForLiveCup(true);
        }
		public void NotifyCommErrorToLocalClient() {
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                if (m_client[i] != null)
                    m_client[i].NotifyCommError();
            }
        }
		public bool CheckAllClientQuit() {
            for (int i = 0; i < (int)BTL_CLIENT_ID.BTL_CLIENT_NUM; i++)
            {
                if (m_client[i] != null && !m_fClientQuit[i])
                    return false;
            }
            return true;
        }
