		private void btlPos_to_cliendID_and_posIdx(global::Dpr.Battle.Logic.BtlPokePos btlPos, out byte clientID, out byte posIdx) {
            clientID = (byte)GetPosCoverClientId(btlPos);
            byte idx = 0;
            if (clientID != (byte)BTL_CLIENT_ID.BTL_CLIENT_NULL)
            {
                byte pos = (byte)btlPos;
                while (pos != 0)
                {
                    pos--;
                    if (clientID == (byte)GetPosCoverClientId((BtlPokePos)pos))
                        idx++;
                }
            }
            posIdx = idx;
        }
		public global::Dpr.Battle.Logic.BtlPokePos PokeIDtoPokePos(global::Dpr.Battle.Logic.POKECON pokeCon, byte pokeID) {
            byte clientID = PokeIDtoClientID(pokeID);
            BTL_PARTY party = pokeCon.GetPartyDataConst(clientID);
            byte memberCount = party.GetMemberCount();
            for (byte i = 0; i < memberCount; i++)
            {
                if (party.GetMemberDataConst(i).GetID() == pokeID)
                {
                    BtlPokePos pos = GetClientPokePos(clientID, i);
                    if (pos != BtlPokePos.POS_NULL)
                        return pos;
                    break;
                }
            }
            return BtlPokePos.POS_NULL;
        }
