		public global::Dpr.Battle.Logic.BtlvPos BtlPosToViewPos(global::Dpr.Battle.Logic.BtlPokePos pos) {
            int isEnemy = ((byte)m_myOrgPos ^ (byte)pos) & 1;
            switch (m_rule)
            {
                case BtlRule.BTL_RULE_DOUBLE:
                    {
                        BtlvPos[][] vposTable = m_setupParam.multiMode == BtlMultiMode.BTL_MULTIMODE_PA_A ? rule_double_vpos_PA_A : rule_double_vpos;
                        byte sidePosIdx = PokemonPosition.PosToSidePosIndex(BtlRule.BTL_RULE_DOUBLE, pos);
                        int row = isEnemy ^ 1;
                        if (row < vposTable.Length && sidePosIdx < vposTable[row].Length)
                            return vposTable[row][sidePosIdx];
                        return BtlvPos.BTL_VPOS_ERROR;
                    }
                case BtlRule.BTL_RULE_RAID:
                    {
                        BtlvPos[][] vposTable;
                        switch (GetSidePosNum(BtlSide.BTL_SIDE_1ST))
                        {
                            case 3: vposTable = rule_raid_vpos3; break;
                            case 2: vposTable = rule_raid_vpos2; break;
                            case 1: vposTable = rule_raid_vpos1; break;
                            default: vposTable = rule_raid_vpos4; break;
                        }
                        if (pos > BtlPokePos.POS_RAID_PLAYER_3)
                            return BtlvPos.BTL_VPOS_FAR_1;
                        byte sidePosIdx = PokemonPosition.PosToSidePosIndex(BtlRule.BTL_RULE_RAID, pos);
                        return vposTable[(byte)m_myOrgPos][sidePosIdx];
                    }
            }
            return (BtlvPos)isEnemy;
        }
