		public uint FixRegularMoney() {
            if (m_fGetMoneyFixed)
                return m_regularMoney;
            uint ratio = calcMoneyDblUpRatio();
            if (ratio > 1)
            {
                m_regularMoney *= ratio;
                m_bonusMoney *= ratio;
                if (m_bonusMoney > DefineConstants.BTL_BONUS_MONEY_MAX)
                    m_bonusMoney = DefineConstants.BTL_BONUS_MONEY_MAX;
            }
            m_regularMoney = (uint)(m_setupParam.moneyRate * (float)m_regularMoney);
            if (m_regularMoney > DefineConstants.BTL_REGULAR_MONEY_MAX)
                m_regularMoney = DefineConstants.BTL_REGULAR_MONEY_MAX;
            m_fGetMoneyFixed = true;
            return m_regularMoney;
        }
		public void AddBonusMoney(uint volume) {
            if (m_fGetMoneyFixed)
                return;
            m_bonusMoney += volume;
            if (m_bonusMoney > DefineConstants.BTL_BONUS_MONEY_MAX)
                m_bonusMoney = DefineConstants.BTL_BONUS_MONEY_MAX;
        }
		public uint GetBonusMoney() {
            if (m_setupParam.bNoGainBattle)
                return 0;
            uint money = m_bonusMoney;
            if (!m_fGetMoneyFixed)
            {
                uint ratio = calcMoneyDblUpRatio();
                if (ratio > 1)
                {
                    money *= ratio;
                    if (money > DefineConstants.BTL_BONUS_MONEY_MAX)
                        money = DefineConstants.BTL_BONUS_MONEY_MAX;
                }
            }
            return money;
        }
		public void SetMoneyDblUp(global::Dpr.Battle.Logic.MoneyDblUpCause cause) {
            if ((int)cause < m_moneyDblUpCause.Length)
                m_moneyDblUpCause[(int)cause] = true;
        }
		private uint calcMoneyDblUpRatio() {
            uint ratio = 1;
            for (int i = 0; i < m_moneyDblUpCause.Length; i++)
            {
                if (m_moneyDblUpCause[i])
                    ratio <<= 1;
            }
            return ratio;
        }
		public uint FixLoseMoney() {
            BATTLE_SETUP_PARAM sp = m_setupParam;
            if (sp.bNoGainBattle || m_fLoseMoneyFixed)
                return 0;
            uint loseMoney;
            if (m_rule == BtlRule.BTL_RULE_RAID || (uint)sp.competitor > (uint)BtlCompetitor.BTL_COMPETITOR_TRAINER)
            {
                loseMoney = 0;
            }
            else
            {
                loseMoney = calc.CalcLoseMoney(sp, m_battleEnvForServer.GetPokeCon());
                m_loseMoney = loseMoney;
            }
            m_fLoseMoneyFixed = true;
            return loseMoney;
        }
