		public bool CanEvolveAfterBattle(in global::Dpr.Battle.Logic.BTL_POKEPARAM poke) {
            uint rootNum = 0;
            if (!poke.PERMFLAG_Get(BTL_POKEPARAM.PermFlag.PERMFLAG_LEVELUP))
                return false;
            byte pokeID = poke.GetID();
            byte clientID = PokeIDtoClientID(pokeID);
            EvolveSituation situation = new EvolveSituation();
            GetEvolveSituation(situation, pokeID);
            PokemonParam pp = poke.GetSrcDataConst();
            PokeParty party = m_srcParty[clientID];
            rootNum = 0;
            ushort monsno = poke.GetMonsNo();
            // The shipped build discards the evolved species and compares the species before and after the call
            // (02037bc4-02037bdc).
            if (PmlUse.Instance.GetEvolveManager() != null)
                PmlUse.Instance.GetEvolveManager().GetEvolvedMonsNo_byLevelUp(pp, party, situation, ref rootNum);
            return monsno != poke.GetMonsNo();
        }
