		private global::Dpr.Battle.Logic.BtlResult checkWinner(byte myClientId) {
            BtlResult result;
            if (m_setupParam.competitor == BtlCompetitor.BTL_COMPETITOR_DEMO_CAPTURE)
            {
                result = BtlResult.BTL_RESULT_WIN;
            }
            else if (m_fCommError)
            {
                result = BtlResult.BTL_RESULT_COMM_ERROR;
            }
            else if (m_setupParam.capturedPokeIdx != DefineConstants.BTL_PARTY_MEMBER_MAX)
            {
                result = BtlResult.BTL_RESULT_CAPTURE;
            }
            else if (m_battleEnvForServer.GetEscapeInfo().GetCount() != 0)
            {
                result = m_battleEnvForServer.GetEscapeInfo().CheckWinner(this, myClientId, GetCompetitor());
            }
            else
            {
                if (m_serverResult == BtlResult.BTL_RESULT_MAX)
                    m_serverResult = BtlResult.BTL_RESULT_WIN;
                result = m_serverResult;
            }
            m_setupParam.result = result;
            if (result == BtlResult.BTL_RESULT_COMM_ERROR)
            {
                m_setupParam.commError = m_iPtrNetClient != null ? m_iPtrNetClient.ErrorKindBits : 0;
                m_setupParam.isDisplayedCommError = Dpr.NetworkUtils.NetworkManager.IsShowApplicationErrorDialog();
            }
            return result;
        }
