		private void Bspstore_RecordData() {
            unsafe
            {
                if (m_setupParam.recBuffer == null || m_setupParam.recordDataMode == BtlRecordDataMode.BTL_RECORDDATA_PLAY)
                    return;
                uint size = 0;
                void* source = m_client[m_myClientID].GetRecordData(ref size);
                if (source != null)
                {
                    Unity.Collections.LowLevel.Unsafe.UnsafeUtility.MemCpy(m_setupParam.recBuffer, source, size);
                    m_setupParam.recDataSize = size;
                    m_setupParam.recRandSeed = m_randomSeed;
                }
            }
        }
