		private void Bspstore_KenteiData() {
            if (m_setupParam.commMode != BtlCommMode.BTL_COMM_NONE)
                return;
            if (m_server == null)
                return;
            BATTLE_KENTEI_RESULT kentei = m_setupParam.kenteiResult;
            kentei.TurnNum = (uint)m_battleEnvForServer.GetBattleCounter().Get(BattleCounter.UniqueCounter.BATTLE_TURN_COUNT);
            kentei.PokeChgNum = (ushort)m_battleEnvForServer.GetBattleCounter().Get(BattleCounter.ClientCounter.MEMBER_CHANGE_COUNT, BTL_CLIENT_ID.BTL_CLIENT_PLAYER);
            AffCounter affCounter = m_battleEnvForServer.GetAffinityCounter();
            kentei.VoidAtcNum = affCounter.GetVoid();
            kentei.WeakAtcNum = affCounter.GetAdvantage();
            kentei.ResistAtcNum = affCounter.GetDisadvantage();
            kentei.VoidNum = affCounter.GetRecvVoid();
            kentei.ResistNum = affCounter.GetRecvDisadvantage();
            if (m_setupParam.result == BtlResult.BTL_RESULT_WIN)
                kentei.WinTrainerNum = 1;
            BTL_PARTY party = m_battleEnvForServer.GetPokeCon().GetPartyData(0);
            byte memberCount = party.GetMemberCount();
            for (byte i = 0; i < memberCount; i++)
            {
                BTL_POKEPARAM bpp = party.GetMemberData(i);
                kentei.UseWazaNum += bpp.WAZA_GetUsedCount();
                kentei.HPSum += (ushort)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
            }
            kentei.LosePokeNum = (ushort)m_battleEnvForServer.GetDeadRec().GetDeadCountByClientID(0);
            kentei.WinPokeNum = m_battleEnvForServer.GetPokeCon().GetPartyData(1).GetDeadMemberCount();
            if (BattleRule.IsClientExist(m_rule, m_setupParam.multiMode, BTL_CLIENT_ID.BTL_CLIENT_ENEMY2))
            {
                BTL_PARTY enemy2Party = m_battleEnvForServer.GetPokeCon().GetPartyData(3);
                if (enemy2Party != null)
                    kentei.WinPokeNum += enemy2Party.GetDeadMemberCount();
            }
        }
