		private void trainerParam_StoreNPCTrainer(global::Dpr.Battle.Logic.TRAINER_DATA dst, global::Dpr.Battle.Logic.BSP_TRAINER_DATA trData) {
            dst.playerStatus = null;
            if (trData == null)
                return;
            dst.trainerData = trData.GetTrainerData();
            dst.instTrainerData = trData.GetInstTrainerData();
            dst.trainerID = trData.GetTrainerID();
            dst.trainerType = trData.GetTrainerType();
            dst.trainerSex = trData.GetTrainerSex();
            dst.trainerGroup = trData.GetTrainerGroup();
            dst.trainerGold = trData.GetGoldParam();
            dst.ai_bit = trData.GetAIBit();
