		public void GetClientTrainerMsg(byte clientID, global::Dpr.Battle.Logic.TrainerMessageID messageID, out string outMessageLabel, out string outSequenceName) {
            outMessageLabel = "";
            outSequenceName = "";
            TRAINER_DATA trData = GetClientTrainerData(clientID);
            if (trData == null)
                return;
            int msgIdx = (int)messageID;
            if (messageID > TrainerMessageID.MESSAGE_LAST_POKE_HP_HALF)
            {
                if (messageID != TrainerMessageID.MESSAGE_LOSE)
                    return;
                if (m_setupParam.competitor == BtlCompetitor.BTL_COMPETITOR_INST)
                {
                    XLSXContent.TowerTrainerTable.SheetTrainerData instData = trData.instTrainerData;
                    int instIdx = (m_serverResult != BtlResult.BTL_RESULT_WIN ? 1 : 0) * 2;
                    outMessageLabel = instData.MsgBattle[instIdx];
                    outSequenceName = instData.MsgBattle[instIdx + 1];
                    return;
                }
                msgIdx = 3;
            }
            TrainerTable.SheetTrainerData data = trData.trainerData;
            if (data == null)
                return;
            if (msgIdx * 2 < data.MsgBattle.Length)
                outMessageLabel = data.MsgBattle[msgIdx * 2];
            if (msgIdx * 2 + 1 < data.MsgBattle.Length)
                outSequenceName = data.MsgBattle[msgIdx * 2 + 1];
        }
		public string GetCliehtTrainerSequence(byte clientID, global::Dpr.Battle.Logic.TrainerSequenceID sequenceID) {
            TRAINER_DATA trData = GetClientTrainerData(clientID);
            if (trData == null)
                return "";
            string[] seqBattle;
            if (m_setupParam.competitor == BtlCompetitor.BTL_COMPETITOR_INST)
            {
                if (trData.instTrainerData == null)
                    return "";
                seqBattle = trData.instTrainerData.SeqBattle;
            }
            else
            {
                if (trData.trainerData == null)
                    return "";
                seqBattle = trData.trainerData.SeqBattle;
            }
            if (seqBattle != null && (int)sequenceID < seqBattle.Length)
                return seqBattle[(int)sequenceID];
            return "";
        }
