		public void PauseTimerForLiveCup() {
            if (m_isFinalizeStarted)
                return;
            BTL_CLIENT client = GetClient(m_myClientID);
            if (client != null)
            {
                GameTimer gameTimer = client.GetGameTimer();
                gameTimer.Pause(GameTimer.TimerType.GAME, TimerControlLevel.LIVE_CUP);
                gameTimer.Pause(GameTimer.TimerType.CLIENT, TimerControlLevel.LIVE_CUP);
                gameTimer.Pause(GameTimer.TimerType.COMMAND, TimerControlLevel.LIVE_CUP);
            }
            if (m_viewCore != null)
                m_viewCore.SetUIControlEnableForLiveCup(false);
        }
		public void RestartTimerForLiveCup(uint gameTimeS) {
            if (m_isFinalizeStarted)
                return;
            BTL_CLIENT client = GetClient(m_myClientID);
            if (client != null)
            {
                GameTimer gameTimer = client.GetGameTimer();
                gameTimer.SetTime(GameTimer.TimerType.GAME, gameTimeS);
                gameTimer.StartCountDown(GameTimer.TimerType.GAME, TimerControlLevel.LIVE_CUP);
                gameTimer.StartCountDown(GameTimer.TimerType.CLIENT, TimerControlLevel.LIVE_CUP);
                gameTimer.StartCountDown(GameTimer.TimerType.COMMAND, TimerControlLevel.LIVE_CUP);
            }
            if (m_viewCore != null)
                m_viewCore.SetUIControlEnableForLiveCup(true);
        }
