		public global::Dpr.Battle.Logic.MainModule.BtlDetailRule GetDetailRule() {
            BATTLE_SETUP_PARAM bp = m_setupParam;
            BtlRule rule = m_rule;
            BtlMultiMode multiMode = bp.multiMode;
            switch (bp.competitor)
            {
                case BtlCompetitor.BTL_COMPETITOR_WILD:
                    if (GetSetupStatusFlag(BTL_STATUS_FLAG.BTL_STATUS_FLAG_LEGEND))
                    {
                        MonsNo monsno = m_setupParam.party[1].GetMemberPointerConst(0).GetMonsNo();
                        if (monsno == MonsNo.DHIARUGA)
                            return BtlDetailRule.Joker1;
                        if (monsno == MonsNo.PARUKIA)
                            return BtlDetailRule.Joker2;
                    }
                    switch (rule)
                    {
                        case BtlRule.BTL_RULE_SINGLE: return BtlDetailRule.WildSingle;
                        case BtlRule.BTL_RULE_DOUBLE: return BtlDetailRule.WildMulti;
                        case BtlRule.BTL_RULE_RAID: return BtlDetailRule.WildSingle;
                        case BtlRule.BTL_RULE_SAFARI: return BtlDetailRule.Safari;
                    }
                    return BtlDetailRule.WildSingle;
                case BtlCompetitor.BTL_COMPETITOR_TRAINER:
                case BtlCompetitor.BTL_COMPETITOR_INST:
                    {
                        TRAINER_DATA enemyTrainer = m_trainerParam[1];
                        if (rule == BtlRule.BTL_RULE_DOUBLE)
                        {
                            switch (multiMode)
                            {
                                case BtlMultiMode.BTL_MULTIMODE_NONE: return BtlDetailRule.TrainerDouble1;
                                case BtlMultiMode.BTL_MULTIMODE_PP_PP: return BtlDetailRule.WildSingle;
                                case BtlMultiMode.BTL_MULTIMODE_PP_AA: return BtlDetailRule.WildSingle;
                                case BtlMultiMode.BTL_MULTIMODE_PA_AA: return BtlDetailRule.TrainerMulti;
                                case BtlMultiMode.BTL_MULTIMODE_P_AA: return BtlDetailRule.TrainerDouble2;
                            }
                            return BtlDetailRule.WildSingle;
                        }
                        if (rule != BtlRule.BTL_RULE_SINGLE)
                            return BtlDetailRule.WildSingle;
                        switch (enemyTrainer.trainerType)
                        {
                            case TrainerType.LEADER1: return BtlDetailRule.L1;
                            case TrainerType.LEADER2: return BtlDetailRule.L2;
                            case TrainerType.LEADER3: return BtlDetailRule.L3;
                            case TrainerType.LEADER4: return BtlDetailRule.L4;
                            case TrainerType.LEADER5: return BtlDetailRule.L5;
                            case TrainerType.LEADER6: return BtlDetailRule.L6;
                            case TrainerType.LEADER7: return BtlDetailRule.L7;
                            case TrainerType.LEADER8: return BtlDetailRule.L8;
                            case TrainerType.BIGFOUR1: return BtlDetailRule.F1;
                            case TrainerType.BIGFOUR2: return BtlDetailRule.F2;
                            case TrainerType.BIGFOUR3: return BtlDetailRule.F3;
                            case TrainerType.BIGFOUR4: return BtlDetailRule.F4;
                            case TrainerType.CHAMPION: return BtlDetailRule.C;
                            case TrainerType.GINGALBOSS: return BtlDetailRule.G1;
                            case TrainerType.GINGALEADER1: return BtlDetailRule.G2;
                            case TrainerType.GINGALEADER2: return BtlDetailRule.G3;
                            case TrainerType.GINGALEADER3: return BtlDetailRule.G4;
                            case TrainerType.KUROTUGU: return BtlDetailRule.BTW;
                        }
                        return BtlDetailRule.TrainerSingle;
                    }
                case BtlCompetitor.BTL_COMPETITOR_COMM:
                    if (rule == BtlRule.BTL_RULE_SINGLE)
                        return BtlDetailRule.TrainerSingle;
                    if (rule == BtlRule.BTL_RULE_DOUBLE)
                    {
                        switch (multiMode)
                        {
                            case BtlMultiMode.BTL_MULTIMODE_PP_PP:
                            case BtlMultiMode.BTL_MULTIMODE_PP_AA:
                            case BtlMultiMode.BTL_MULTIMODE_PA_AA:
                                return BtlDetailRule.TrainerMulti;
                            case BtlMultiMode.BTL_MULTIMODE_P_AA:
                                return BtlDetailRule.TrainerDouble2;
                        }
                        return BtlDetailRule.TrainerDouble1;
                    }
                    return BtlDetailRule.WildSingle;
                case BtlCompetitor.BTL_COMPETITOR_DEMO_CAPTURE:
                    return BtlDetailRule.WildSingle;
            }
            return BtlDetailRule.WildSingle;
        }
		public byte GetBallDecoSeals(byte pokeID, ref global::Dpr.BallDeco.AffixSealData[] sealData) {
            byte clientID = PokeIDtoClientID(pokeID);
            BTL_POKEPARAM bpp = m_battleEnvForClient.GetPokeCon().GetPokeParamConst(pokeID);
            PokemonParam pp = bpp.GetSrcDataConst();
            byte memberIdx = PokeID.PokeIdToStartMemberIndex(pokeID);
            ref CapsuleData capsuleData = ref GetBallDeco(clientID, pp, memberIdx);
            sealData = capsuleData.AffixSealDatas;
            return capsuleData.AffixSealCount;
        }
		private ref global::Dpr.BallDeco.CapsuleData GetBallDeco(byte clientID, global::Pml.PokePara.PokemonParam pp, int index) {
            uint id = pp.GetID();
            uint personalRnd = pp.GetPersonalRnd();
            if ((id | personalRnd) != 0)
            {
                CapsuleData[] capsuleDatas = m_setupParam.ballDecoDesc[clientID];
                if (index >= 0 && index < capsuleDatas.Length
                    && capsuleDatas[index].AttachPokemonId == id && capsuleDatas[index].AttachPersonalRnd == personalRnd)
                {
                    return ref capsuleDatas[index];
                }
            }
            return ref DummyCapsuleData;
        }
		public bool IsTurearukiPokemon(global::Pml.PokePara.PokemonParam pp) {
            if (FieldManager.fwMng == null)
                return false;
            if (!FieldManager.fwMng.IsCanTurearuki(pp))
                return false;
            PokemonParam partner = FieldManager.fwMng.PartnerPokeParam;
            if (partner == null)
                return false;
            if (pp.GetID() != partner.GetID())
                return false;
            return pp.GetPersonalRnd() == partner.GetPersonalRnd();
        }
